9066608],[-49.234200442275245,-16.672561977979786],[-49.23518452152466,-16.673811169901466],[-49.2321012566894,-16.672917006327957],[-49.231711064317295,-16.672961681250577],[-49.231428999082006,-16.673275148724354],[-49.231459509265775,-16.67368905016262],[-49.23183249153836,-16.674090409402716],[-49.23638539390022,-16.675405137586655],[-49.23717090630002,-16.676970093052038],[-49.23740658839824,-16.677299310878208],[-49.238305347415135,-16.679197189691646],[-49.23863007135092,-16.679469624091443],[-49.238902584677966,-16.67949018064373],[-49.23924812975939,-16.679349253593966],[-49.23942488421053,-16.67914828182836],[-49.23947794245676,-16.678837706435075],[-49.239345552120504,-16.678445545878787],[-49.2379966183842,-16.675896006943546],[-49.24138906040786,-16.67687108954736],[-49.241471443539915,-16.677161039021517],[-49.241724086381694,-16.677482470273688],[-49.24217617128965,-16.677788010355044],[-49.242558845892745,-16.67790107955065],[-49.24296545282241,-16.677920129603187],[-49.24467273474974,-16.678510423230435],[-49.24542814973849,-16.678514707670825],[-49.24593065181475,-16.678225376896634],[-49.248836937503704,-16.67906319479543],[-49.24922343314474,-16.679021419718545],[-49.249620230504,-16.679127517202996]]]}$q$), 4326), $q${"regra_id":"goiania_zrt1_portaria224_2011","municipio":"Goiânia","ibge":"5208707","uf":"GO","tipo":"zona","regime":"Zona de Restricao de Trafego 1 (ZRT-1)","nome":"Goiania: Portaria 224/2011-AMT (arts. 2, 3 e 7; art. 3 com redacao da Portaria 70/2013-SMT; Anexo I com item 14 da Portaria 21/2015-SMT), caminhoes acima de 8,30 t ou acima de 8,0 m na Zona de Restricao de Trafego 1 (area central e Setor Leste Universitario), seg-sex 7h-19h","status":"ativa","confianca":"media","janelas":[{"days":[1,2,3,4,5],"from":"07:00","to":"19:00"}],"feriados":"suspende","alvo":{"caminhao":true,"qualquer":[{"campo":"pbt_t","acima":8.3},{"campo":"comprimento_m","acima":8.0}]},"excecoes":["Portaria 224 art. 3 (red. Portaria 70/2013): so atinge caminhao acima de 8,30 t (PBT) / acima de 8,0 m; art. 7: Veiculo Urbano de Carga ate 7,0 t e ate 8,0 m circula em periodo integral","Portaria 224 art. 7, em periodo integral: caminhoes de urgencia, obras e servicos de infraestrutura urbana, socorro mecanico de emergencia, guincho, cobertura jornalistica, obras e servicos de emergencia, Correios, sinalizacao de transito, coleta de lixo, transporte de valores","Portaria 224 art. 7, das 8h as 16h: concretagem e concretagem-bomba, caminhao guindaste, remocao de terra em obras civis, mudanca, transporte de produtos alimenticios pereciveis; remocao de entulho/cacambas segue o regulamento da AMT (Decreto 286/04)","Portaria 224 art. 6: prestadores de servico de utilidade publica em servico, caracterizados (CTB art. 29, VIII)","Lei 9.028/2011 art. 3: onibus e veiculos das Forcas Armadas, policias e bombeiros em servico","Portaria 224 art. 5: a AMT pode fixar condicoes especificas e emitir autorizacao especial em situacoes extraordinarias"],"base_legal":[{"ato":"Portaria 224/2011-AMT, de 18/10/2011 (Agencia Municipal de Transito, Transportes e Mobilidade; DOM Goiania no 5.214, 21/10/2011, p. 9-11), regulamenta a Lei 9.028/2011","artigo":"art. 1 (trafego de veiculos pesados e caminhoes na Zona de Restricao de Trafego sujeito as normas da Portaria); art. 2 (zona = area limitada pelos logradouros do Anexo I e configurada no mapa do Anexo II); art. 7 (excecoes); art. 6, 5; art. 10 (vigencia 20/10/2011)","url":"https://www.goiania.go.gov.br/Download/legislacao/diariooficial/2011/do_20111021_000005214.pdf","nota":"Texto integral lido no PDF oficial do DOM (atos/5208707/portaria_224_2011_amt.txt). Anexo II e mapa raster; Anexo I lista 13 logradouros limitadores."},{"ato":"Portaria 70/2013-SMT, de 10/10/2013 (DOM Goiania no 5.697, 14/10/2013, p. 106-107)","artigo":"art. 1 (nova redacao do art. 3 da Portaria 224/2011: Zona de Restricao de Trafego 1; caminhoes acima de 8,30 toneladas / acima de 8,0 metros; 7h as 19h, 2a a 6a feira); art. 3 (vigencia 180 dias apos a publicacao = 12/04/2014)","url":"https://www.goiania.go.gov.br/Download/legislacao/diariooficial/2013/do_20131014_000005697.pdf","nota":"Lida no PDF oficial do DOM e no texto do Querido Diario (atos/5208707/portaria_70_2013_smt.txt). A tabela traz uma unica linha (colunas Caminhoes / Comprimento / Horario) sem conectivo e/ou: lida como restricao se exceder QUALQUER dos dois limites, coerente com a isencao do art. 7 (ate 7,0 t E ate 8,0 m)."},{"ato":"Portaria 21/2015-SMT, de 13/03/2015 (DOM Goiania no 6.045, 18/03/2015)","artigo":"art. 1 (acrescenta o item 14, Av. E, Jardim Goias, ao Anexo I da Portaria 224/2011); art. 2 (vigencia na data da assinatura)","url":"https://www.goiania.go.gov.br/Download/legislacao/diariooficial/2015/do_20150318_000006045.pdf","nota":"atos/5208707/portaria_21_2015_smt.txt"},{"ato":"Lei municipal 9.028, de 20/04/2011 (DOM Goiania 5.091, 25/04/2011)","artigo":"art. 1 (veda veiculos pesados e caminhoes seg-sex, exceto feriados, nos horarios de intenso transito conforme regulamentacao); art. 3 (excecoes); art. 5 (sinalizacao)","url":"https://data.queridodiario.ok.org.br/5208707/2011-04-25/46e84d8199afe8764cdc8f072a31091bd78b8582.txt","nota":"Citada como vigente em 15/07/2025 e 18/12/2025 (pareceres de veto no DOM), junto com as Portarias 224/2011, 70/2013 e 21/2015."}],"nota":"Polígono aproximado da ZRT-1 (Portaria 224/2011-AMT, Anexo I; Anexo II é mapa raster não georreferenciado) montado sobre as vias-limite do OSM: Av. Independência, Rua 74, Rua 68, Av. Paranaíba, Al. Botafogo, Rua 10, Rua 94, Av. Assis Chateaubriand e Al. dos Buritis (Setor Central e arredores) mais o corredor da Av. Universitária, Praça Universitária e Rua 261 (faixa de 60 m). Av. E (Jardim Goiás, item 14) fora: ponto isolado sem área definida. Ampliado 25 m para o recuo de 20 m manter as vias-limite na zona.","vigencia_inicio":"2014-04-12","autorizacao":"Autorizacao especial da Secretaria Municipal de Engenharia de Transito (ex-AMT/SMT), Portaria 224/2011 art. 5","fonte_geometria":"Anexo I da Portaria 224/2011 (logradouros limitadores; Anexo II é mapa raster sem coordenadas) georreferenciado à mão sobre as vias do OSM (cache do PBF sse_co); aproximado.","origem_destino_dentro":"avisa","vuc":null,"vuc_nota":"Não há definição local de VUC; o Veículo Urbano de Carga até 7,0 t e 8,0 m é isento da ZRT-1 (art. 7), e o alvo (acima de 8,3 t ou 8,0 m) já o deixa de fora.","aproximado":true,"verificado_em":"2026-10-18"}$q$::jsonb, $q$2014-04-12$q$::timestamptz, null::timestamptz)
