insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$goiania$q$, $q$https://www.goiania.go.gov.br/Download/legislacao/diariooficial/2011/do_20111021_000005214.pdf (Portaria 224/2011-AMT, DOM 5.214); https://www.goiania.go.gov.br/Download/legislacao/diariooficial/2013/do_20131014_000005697.pdf (Portaria 70/2013-SMT); https://www.goiania.go.gov.br/Download/legislacao/diariooficial/2015/do_20150318_000006045.pdf (Portaria 21/2015-SMT); Lei 9.028/2011$q$, $q$Atos oficiais de Goiânia: domínio público (Lei 9.610/1998, art. 8º, IV). Polígono da ZRT-1 montado sobre as vias do OpenStreetMap (PBF local): derivado do OSM, ODbL 1.0 (© colaboradores do OpenStreetMap), base derivada separada do OSM.$q$, 1, $q$Lei 9.028/2011 (art. 1) regulamentada pela Portaria 224/2011-AMT, com nova redação do art. 3 pela Portaria 70/2013-SMT (vigência 12/04/2014) e item 14 do Anexo I pela Portaria 21/2015-SMT. Vigência confirmada por citação nos DOM de 15/07/2025 e 18/12/2025; sem portaria posterior. Confiança média: a tabela da Portaria 70/2013 não traz conectivo (lida como OU), o Anexo II é mapa sem coordenadas (zona aproximada) e o ato não diz se vale em feriado. A regra da cegonha (art. 4) fica desativada: o perfil de veículo não tem a classe CTV.$q$);
